package serviceidentityrotation

import (
	"bytes"
	"context"
	"crypto/tls"
	"crypto/x509"
	"net/url"
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/nats-io/nats.go"
	"terrascale.tech/orchestrator/src/orchestrator/bootstrapcredentials"
	"terrascale.tech/orchestrator/src/orchestrator/cloudflare"
	"terrascale.tech/orchestrator/src/orchestrator/hostsecrets"
	"terrascale.tech/orchestrator/src/orchestrator/provider"
)

// FileConfig contains deployment references only. The identity-service secret
// is generated by the live global controller, never accepted from config.
type FileConfig struct {
	Region              string                 `json:"region"`
	CompartmentID       string                 `json:"compartment_id"`
	VaultID             string                 `json:"vault_id"`
	KeyID               string                 `json:"key_id"`
	CloudflareAccountID string                 `json:"cloudflare_account_id"`
	CloudflareTokenFile string                 `json:"cloudflare_token_file"`
	DashboardScript     string                 `json:"dashboard_script"`
	CertificateFile     string                 `json:"certificate_file"`
	PrivateKeyFile      string                 `json:"private_key_file"`
	TrustBundleFile     string                 `json:"trust_bundle_file"`
	Members             []RemoteMemberEndpoint `json:"members"`
	PeriodSeconds       int64                  `json:"period_seconds"`
	OverlapSeconds      int64                  `json:"overlap_seconds"`
}

func (c FileConfig) Validate() error {
	if !provider.ValidOCIRegion(c.Region) || !provider.IsOCID(strings.Replace(c.CompartmentID, "..", ".global.", 1), "compartment") || !provider.IsOCID(c.VaultID, "vault") || !provider.IsOCID(c.KeyID, "key") || c.PeriodSeconds < 3600 || c.PeriodSeconds > 31*86400 || c.OverlapSeconds < 60 || c.OverlapSeconds > 300 || len(c.Members) == 0 || len(c.Members) > 1024 {
		return ErrRotation
	}
	if len(c.CloudflareAccountID) != 32 || !fileToken(c.CloudflareAccountID) || len(c.DashboardScript) > 128 || !fileToken(c.DashboardScript) {
		return ErrRotation
	}
	for _, p := range []string{c.CloudflareTokenFile, c.CertificateFile, c.PrivateKeyFile, c.TrustBundleFile} {
		if !filepath.IsAbs(p) || filepath.Clean(p) != p || strings.ContainsAny(p, "\x00\r\n") {
			return ErrRotation
		}
	}
	seen := map[string]bool{}
	urls := map[string]bool{}
	for _, member := range c.Members {
		u, e := url.Parse(member.URL)
		if e != nil || u.Scheme != "https" || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || u.Opaque != "" || u.RawPath != "" || (u.Path != "" && u.Path != "/") || !fileToken(member.NodeID) || seen[member.NodeID] || urls[u.Host] {
			return ErrRotation
		}
		seen[member.NodeID] = true
		urls[u.Host] = true
	}
	return nil
}
func fileToken(s string) bool {
	if len(s) == 0 || len(s) > 128 {
		return false
	}
	for _, c := range s {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == '_') {
			return false
		}
	}
	return true
}
func (c FileConfig) Construct(ctx context.Context, connection *nats.Conn, candidate string, epoch uint64, leaseID string, check func(context.Context) error) (*Coordinator, error) {
	if ctx == nil || check == nil || c.Validate() != nil || check(ctx) != nil {
		return nil, ErrRotation
	}
	store, e := NewNATSStore(connection, candidate, epoch, leaseID, check)
	if e != nil {
		return nil, ErrRotation
	}
	configuration, e := hostsecrets.NewInstanceConfiguration(ctx, c.Region)
	if e != nil {
		return nil, ErrRotation
	}
	issuer, e := hostsecrets.NewIdentitySecretIssuer(hostsecrets.IdentitySecretIssuerConfig{Provider: configuration, Region: c.Region, CompartmentID: c.CompartmentID, VaultID: c.VaultID, KeyID: c.KeyID, Authority: check})
	if e != nil {
		return nil, ErrRotation
	}
	token, e := bootstrapcredentials.ReadFile(c.CloudflareTokenFile, true, 4096)
	if e != nil {
		return nil, ErrRotation
	}
	defer clear(token)
	token = bytes.TrimSuffix(token, []byte("\n"))
	if len(token) < 32 || bytes.ContainsAny(token, " \t\r\n") {
		return nil, ErrRotation
	}
	cert, e := bootstrapcredentials.ReadFile(c.CertificateFile, false, 128<<10)
	if e != nil {
		return nil, ErrRotation
	}
	defer clear(cert)
	key, e := bootstrapcredentials.ReadFile(c.PrivateKeyFile, true, 128<<10)
	if e != nil {
		return nil, ErrRotation
	}
	defer clear(key)
	trust, e := bootstrapcredentials.ReadFile(c.TrustBundleFile, false, 128<<10)
	if e != nil {
		return nil, ErrRotation
	}
	defer clear(trust)
	pair, e := tls.X509KeyPair(cert, key)
	if e != nil {
		return nil, ErrRotation
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(trust) {
		return nil, ErrRotation
	}
	endpoints := slices.Clone(c.Members)
	members, e := NewRemoteMembers(RemoteMembersConfig{TLS: &tls.Config{MinVersion: tls.VersionTLS13, RootCAs: roots, Certificates: []tls.Certificate{pair}}, Endpoints: func(ctx context.Context) ([]RemoteMemberEndpoint, error) {
		if check(ctx) != nil {
			return nil, ErrRotation
		}
		return slices.Clone(endpoints), nil
	}, Authority: func(ctx context.Context) (uint64, string, error) {
		if check(ctx) != nil {
			return 0, "", ErrRotation
		}
		return epoch, leaseID, nil
	}})
	if e != nil {
		return nil, ErrRotation
	}
	return New(Config{Issuer: issuer, Store: store, Dashboard: cloudflare.NewClient(string(token), "", c.CloudflareAccountID), Members: members, Script: c.DashboardScript, Period: time.Duration(c.PeriodSeconds) * time.Second, Overlap: time.Duration(c.OverlapSeconds) * time.Second, Authority: check})
}
